  initializeHandler: vi.fn(),
  handleMessage: vi.fn(),
  shutdown: vi.fn(),
}));

vi.mock('../../src/task/manager.js', () => ({
  getTaskManager: vi.fn(() => ({
    getRunningTask: vi.fn(() => null),
    hasRunningTask: vi.fn(() => false),
  })),
}));

